mapper.update:

/* setBntTrxlMasterWmreReturnMultiUplolad */
	INSERT INTO BNTTRXL
	(
		  DOC_NAME				-- 'BNTWMRE'
		 ,TARGET				-- BUYER_CODE
		 ,KEY_1					-- PO_NO
		 ,KEY_2					-- PO_SEQ
		 ,KEY_3					-- B_REQ_DATE
		 ,KEY_4					-- WMRE_TYPE
		 ,KEY_5					-- WMRE_QTY
		 ,KEY_6					-- B_REQ_REMARK
		 ,KEY_7					-- M_REC_DATE
		 ,KEY_8					-- M_REC_REMARK
		 ,KEY_9					-- WMRE_TYPE2
		 ,KEY_10				-- WMRE_TYPE3
		 ,KEY_11				-- WMRE_TYPE_DETAIL
		 ,KEY_12				-- ADD_USER_ID
		 ,KEY_13				-- DELIVERY_FLAG
		 ,KEY_14				-- ' '
		 ,KEY_15				-- ' '
	)
	VALUES(
		  'BNTWMRE'
		 ,#{BUYER_CODE}
	     ,#{PO_NO}
	     ,#{PO_SEQ}
	     ,#{B_REQ_DATE}
	     ,#{WMRE_TYPE}
	     ,#{WMRE_QTY}
	     ,#{B_REQ_REMARK}
	     ,#{M_REC_DATE}
	     ,#{M_REC_REMARK}
	     ,#{WMRE_TYPE2}
	     ,#{WMRE_TYPE3}
	     ,#{WMRE_TYPE_DETAIL}
	     ,#{st_user_id}
	     ,NVL(#{DELIVERY_FLAG}, ' ')
	     ,' '
	     ,' '
	 )


/* deleteBntTrxlMasterWmreReturnMultiUplolad */
		DELETE FROM BNTTRXL
		      WHERE DOC_NAME = 'BNTWMRE'
		        AND TARGET = #{BUYER_CODE}
		        AND KEY_1 = #{PO_NO}
		        AND KEY_2 = #{PO_SEQ}


/* initBntTrxlMasterWmreReturnMultiUplolad */
	DELETE	BNTTRXL
	WHERE	DOC_NAME = 'BNTWMRE'
	AND		KEY_12 = #{st_user_id}


/*	insertMasterWmreReturnMulti */
	INSERT INTO BNTWMRE
	(
		WMRE_NO
		,BUYER
		,PO_NO
		,PO_SEQ
		,LEGACY_PO_NO
		,LEGACY_PO_SEQ
		,BUYER_ITEM_NO
		,DESCRIPTION
		,SPECIFICATION
		,ITEM_QTY
		,UNIT_MEASURE
		,SELLER
		,PROCESS_TYPE
		,BUYER_DEPT_CODE
		,BUYER_PERSON_NAME
		,BUYER_PERSON_TEL
		,WAREHOUSE_CODE
		,ADD_USER_ID
		,PROCESS_USER_NAME
		,WMRE_QTY
		,WMRE_TYPE
		,WMRE_TYPE2
		,WMRE_TYPE3
		,WMRE_TYPE_DETAIL
		,B_REQ_DATE
		,B_REQ_USER_ID
		,B_REQ_FLAG
		,M_REC_DATE
		,M_REC_USER_ID
		,M_REC_FLAG
		,FLAG
		,B_REQ_REMARK
		,M_REC_REMARK
		,DELIVERY_FLAG
	)
	VALUES
	(
		(
			SELECT	'WM'||TO_CHAR(SYSDATE,'YYMMDD')|| LPAD(COUNT(WMRE_NO)+1,3,0) AS WMRE_NO
			FROM	BNTWMRE
			WHERE	SUBSTR(WMRE_NO,3,6) = TO_CHAR(SYSDATE,'YYMMDD')	
		)
		,#{BUYER_CODE}
		,#{PO_NO}
		,#{PO_SEQ}
		,#{LEGACY_PO_NO}
		,#{LEGACY_PO_SEQ}
		,#{BUYER_ITEM_NO}
		,#{DESCRIPTION}
		,#{SPECIFICATION}
		,#{ITEM_QTY}
		,#{UNIT_MEASURE}
		,#{SELLER}
		,#{PROCESS_TYPE}
		,#{BUYER_DEPT_CODE}
		,#{BUYER_USER_NAME}
		,#{BUYER_USER_TEL}
		,#{WAREHOUSE_CODE}
		,#{st_user_id}
		,#{BUYER_USER_NAME}
		,#{WMRE_QTY}
		,#{WMRE_TYPE}
		,#{WMRE_TYPE2}
		,#{WMRE_TYPE3}
		,#{WMRE_TYPE_DETAIL}
		,#{B_REQ_DATE}
		,#{st_user_id}
		,'02'
		,#{M_REC_DATE}
		,#{st_user_id}
		,'02'
		,'02'
		,#{B_REQ_REMARK}
		,#{M_REC_REMARK}
		,#{DELIVERY_FLAG}
	)
